V = {
1: ('سأل سائل بعذاب واقع', 'نمونه می\u200cگوید تقاضاکننده\u200cای تقاضای عذاب کرد که واقع شد و در شأن نزول مشهور پس از نصب علی علیه\u200cالسلام در غدیر خم نعمان بن حارث گفت اگر این سخن حق است سنگی از آسمان بر ما بباران و همان شد و علامه امینی در الغدیر این روایت را از سی تن از عالمان اهل\u200cسنت نقل کرده است', ''),
2: ('للكافرين ليس له دافع', 'نمونه می\u200cگوید این عذاب مخصوص کافران است و هیچ\u200cکس نمی\u200cتواند آن را دفع کند و پیوند این آیه با سائل آیه پیش آن است که عذاب خواسته\u200cشده حیطه\u200cاش کافران\u200cاند و هیچ قدرت بشری و هیچ شفاعت بی\u200cاذنی در برابر فرمان قطعی خدا کارگر نیست و همین قطعیت مایه انذار شنونده است', ''),
3: ('من الله ذي المعارج', 'نمونه می\u200cگوید این عذاب از سوی خداوند ذی المعارج است و معارج جمع معرج یعنی پله و محل صعود و خداوند مقامات مختلفی برای فرشتگان قرار داده که با سلسله مراتب به سوی قرب او پیش می\u200cروند و همین فرشتگان مأمور اجرای عذاب درباره مجرمان\u200cاند و برخی معارج را فضائل الهی دانسته\u200cاند ولی معنای نخست مناسب\u200cتر است', ''),
4: ('تعرج الملائکة والروح إليه', 'نمونه می\u200cگوید فرشتگان و روح به سوی او عروج می\u200cکنند در روزی که مقدارش پنجاه هزار سال است و روح در اینجا فرشته\u200cای بزرگ یا جبرئیل دانسته شده و درازی آن روز به درازی صحنه\u200cهای قیامت یا مراتب عروج باز می\u200cگردد و این درازی بر دشواری و سنگینی آن روز برای کافران دلالت دارد', ''),
5: ('فاصبر صبرا جميلا', 'نمونه می\u200cگوید پس صبری زیبا پیشه کن و صبر جمیل صبری است که در آن شکوه به خلق و جزع و بی\u200cتابی نباشد و این فرمان پس از سخن از درازی روز قیامت تسلی پیامبر در برابر استهزا و شتاب\u200cخواهی کافران برای عذاب است و راه مبلغان حق را در همه عصرها روشن می\u200cکند', ''),
6: ('إنهم يرونه بعيدا', 'نمونه می\u200cگوید کافران آن روز و عذاب را دور می\u200cبینند و دوردیدن آنان هم از انکار معاد سرچشمه می\u200cگیرد و هم از غفلت از کوتاهی عمر دنیا و همین دورپنداری است که آنان را به شتاب\u200cخواهی تمسخرآمیز وامی\u200cدارد و پرس و جوی عذاب را به بازی می\u200cگیرد و صبر پیامبر پاسخ همین افق تنگ است', ''),
7: ('ونراه قريبا نزدیکی قطعی', 'نمونه می\u200cگوید ما آن را نزدیک می\u200cبینیم و نزدیکی در علم و قدرت خدا با دورپنداری انسان سنجیده نمی\u200cشود و هر آینده قطعی\u200cالوقوعی در برابر علم الهی حاضر و نزدیک است و این تقابل دو دیدگاه یعنی افق محدود انسان و افق علم خدا بنیاد انذار این آیات و آرامش پیامبر در برابر تکذیب\u200cهاست', ''),
8: ('تكون السماء كالمهل', 'نمونه می\u200cگوید روزی که آسمان همچون مهل می\u200cشود و مهل فلز گداخته است و گاه درد ته\u200cنشین روغن زیتون و آسمان\u200cهای استوار ذوب و متلاشی می\u200cشوند و پس از این ویرانی جهانی نوین ایجاد می\u200cگردد و انسان\u200cها حیات نو خود را از سر می\u200cگیرند و نظام کنونی پایان می\u200cپذیرد', ''),
9: ('تكون الجبال كالعهن', 'نمونه می\u200cگوید کوه\u200cها مانند عهن یعنی پشم رنگین زده\u200cشده خواهند بود و کوه\u200cها در هم کوبیده و خرد و با تندباد در فضا پراکنده می\u200cشود همچون پشمی که باد با خود ببرد و چون کوه\u200cها رنگ\u200cهای مختلف دارند به پشم\u200cهای رنگین تشبیه شده\u200cاند و سخت\u200cترین پدیده\u200cها سبک\u200cترین می\u200cشوند', ''),
10: ('لا يسأل حميم حميما', 'نمونه می\u200cگوید هیچ دوست صمیمی سراغ دوستش را نمی\u200cگیرد زیرا وضع حساب آن\u200cچنان وحشتناک است که همه در فکر خویش\u200cاند و احدی به دیگری نمی\u200cپردازد و چنان\u200cکه در سوره عبس آمده هر کس آن روز گرفتاری\u200cای دارد که او را از دیگران باز می\u200cدارد و هول صحنه جایی برای شفاعت\u200cجویی دوستانه نمی\u200cگذارد', ''),
11: ('يود المجرم لو يفتدي ببنيه', 'نمونه می\u200cگوید دوستان را به آنان نشان می\u200cدهند ولی هر کس گرفتار کار خویش است و گنهکار دوست دارد فرزندان خود را در برابر عذاب آن روز فدا کند و یود دوست\u200cداشتن همراه تمناست و فدا حفظ خود از مصیبت با پرداخت چیزی است و عزیزترین سرمایه انسان نخستین چیزی است که در آن تنگنا به ذهن می\u200cآید', ''),
12: ('وصاحبته وأخيه فدای همسر و برادر', 'نمونه می\u200cگوید مجرم دوست دارد همسر و برادرش را نیز فدا کند و ترتیب ذکر از فرزند به همسر و برادر گسترش دایره عزیزترین\u200cهاست و هر پیوندی که در دنیا تکیه\u200cگاه انسان بود در آن روز به بهای نجات او عرضه می\u200cشود و این آرزو خود گواه شدت عذاب و بی\u200cبازگشت\u200cبودن صحنه است', ''),
13: ('وفصيلته التي تؤويه', 'نمونه می\u200cگوید مجرم فصیلة خود را نیز می\u200cخواهد فدا کند و فصیله عشیره و فامیلی است که انسان از آن جدا شده و تؤویه یعنی پناه\u200cدادن و قبیله\u200cای که همیشه از او حمایت می\u200cکرد امروز بهای رهايي او شمرده می\u200cشود و همه سرمایه\u200cهای اجتماعی انسان در آن روز فرو می\u200cریزد', ''),
14: ('ومن في الأرض جميعا ثم ينجيه', 'نمونه می\u200cگوید مجرم حاضر است تمام مردم روی زمین را فدا کند تا مایه نجاتش شود و تعبیر ثم نشان می\u200cدهد آنان می\u200cدانند این فداها بعید است اثر کند زیرا ثم برای فاصله و تراخی می\u200cآید و پاسخ همه این تمناها کلا است و هیچ فدیه\u200cای در آن دادگاه پذیرفته نمی\u200cشود', ''),
15: ('كلا إنها لظى', 'نمونه می\u200cگوید هرگز چنین نیست و هیچ فدیه و فدایی پذیرفته نمی\u200cشود و آن شعله\u200cهای سوزان آتش است که پیوسته زبانه می\u200cکشد و هرچه در کنار و مسیر خود یابد می\u200cسوزاند و لظی شعله خالص آتش و از نام\u200cهای جهنم است و در این آیه هر دو معنا ممکن است', ''),
16: ('نزاعة للشوى کندن اطراف', 'نمونه می\u200cگوید آتش دست و پا و پوست سر را می\u200cکند و می\u200cبرد و نزاعه چیزی است که پی\u200cدرپی جدا می\u200cکند و شوی به معنای دست و پا و اطراف بدن است و برخی آن را پوست تن یا گوشت ساق پا گفته\u200cاند و هنگام رسیدن آتش سوزان نخست اطراف و جوانب چیز را می\u200cسوزاند و عجیب آنکه با این همه مصیبت مرگی در کار نیست', ''),
17: ('تدعو من أدبر وتولى', 'نمونه می\u200cگوید این شعله سوزان کسانی را که پشت به فرمان خدا کردند و از اطاعت او روی گرداندند صدا می\u200cزند و به سوی خود می\u200cخواند و آتش یا با زبان حال و جاذبه ویژه\u200cاش نسبت به مجرمان و یا با زبان قال آنان را فرا می\u200cخواند و طعمه آن پشت\u200cکنندگان به ایمان و طاعت\u200cاند', ''),
18: ('وجمع فأوعى ذخیره\u200cکنندگان مال', 'نمونه می\u200cگوید آتش کسانی را می\u200cخواند که اموال را جمع و ذخیره کردند و در راه خدا انفاق نکردند و دائما در فکر جمع مال از حرام و حلال بودند بی\u200cآنکه به حقوق مستمندان توجه کنند یا فلسفه این نعمت الهی را بدانند و این دو صفت پشت به ایمان و دلبستگی به ذخیره\u200cکردن خلاصه راه دوزخیان است', ''),
19: ('إن الإنسان خلق هلوعا', 'نمونه می\u200cگوید انسان هلوع آفریده شده است و هلوع را جمعی حریص و جمعی کم\u200cطاقت تفسیر کرده\u200cاند و هر دو معنا در این واژه جمع است زیرا این دو وصف لازم و ملزوم یکدیگرند و آدم\u200cهای حریص غالبا بخیل\u200cاند و در برابر حوادث سوء کم\u200cتحمل و آیات بعد همین هلع را تفسیر می\u200cکند', ''),
20: ('إذا مسه الشر جزوعا', 'نمونه می\u200cگوید هنگامی که بدی به او رسد بسیار جزع و بی\u200cتابی می\u200cکند و این بی\u200cتابی شاخه\u200cای از همان هلع است و پرسش آنکه خدا انسان را برای سعادت آفریده چگونه شر در طبیعت اوست پاسخش آن است که غرائز بالقوه وسیله کمال\u200cاند و اگر در مسیر انحرافی افتند مایه نکبت می\u200cشوند', ''),
21: ('وإذا مسه الخير منوعا', 'نمونه می\u200cگوید و هنگامی که خوبی به او رسد از دیگران دریغ می\u200cدارد و منع خیر روی دیگر هلع است و حرص چون نیروی عطش کمال است اگر در مسیر علم افتد مایه کمال و اگر در مسیر مادیات افتد مایه بخل و شر می\u200cشود و احسن تقویم بودن آفرینش با همین سرباززدن غرائز از مسیر درست سازگار است', ''),
22: ('إلا المصلين استثنای نمازگزاران', 'نمونه می\u200cگوید مگر نمازگزاران و این استثنا نشان می\u200cدهد انسان اسیر هلع سرنوشت محتوم نیست و نه صفت برجسته مؤمنان در برابر این آسیب شمرده می\u200cشود و نماز نخستین و مهم\u200cترین آن\u200cهاست چرا که ارتباط مستمر با درگاه خدا انسان را از غفلت و غرور و اسارت شهوات باز می\u200cدارد', ''),
23: ('على صلاتهم دائمون تداوم نماز', 'نمونه می\u200cگوید نمازگزاران کسانی\u200cاند که نمازهای خود را تداوم می\u200cبخشند نه آنکه همیشه در حال نماز باشند بلکه در وقت\u200cهای معین نماز را انجام دهند و هر کار خیری آنگاه اثر مثبت دارد که تداوم داشته باشد و از امام باقر علیه\u200cالسلام نقل است که این آیه اشاره به نافله و آیه يحافظون ناظر به فریضه است', ''),
24: ('في أموالهم حق معلوم', 'نمونه می\u200cگوید در اموال نمازگزاران حق معلومی است برای نیازمندان و برخی آن را زکات دانسته\u200cاند ولی این سوره مکی است و حکم زکات در مکه نازل نشده بود پس مراد چیزی غیر از زکات است که انسان بر خود لازم می\u200cشمرد و حدیث امام صادق علیه\u200cالسلام همین را تأیید می\u200cکند که از ثروت خود جدا کند و به خویشان و نیازمندان برساند', ''),
25: ('للسائل والمحروم دو نیازمند', 'نمونه می\u200cگوید آن حق معلوم برای سائل و محروم است و سائل کسی است که حاجت خود را می\u200cگوید و تقاضا می\u200cکند و محروم کسی است که شرم و حیا مانع تقاضای اوست و در حدیث امام صادق علیه\u200cالسلام محروم کسی است که در کسب و کارش می\u200cکوشد ولی زندگی او پیچیده شده و انجام این حق هم مبارزه اجتماعی با فقر است و هم شست\u200cوشوی دل از حرص و بخل', ''),
26: ('يصدقون بيوم الدين', 'نمونه می\u200cگوید آنان به روز جزا ایمان دارند و تعبیر يصدقون که فعل مضارع است دلالت بر استمرار دارد و پیوسته توجه دارند که حساب و کتاب و جزایی در کار است و برخی آن را تصدیق عملی یعنی انجام وظائف و ترک محرمات دانسته\u200cاند و ظاهر آیه هر دو تصدیق علمی و عملی را شامل می\u200cشود', ''),
27: ('من عذاب ربهم مشفقون', 'نمونه می\u200cگوید آنان از عذاب پروردگارشان بیمناک\u200cاند و حسنات خود را ناچیز و سيئات خویش را بزرگ می\u200cشمارند و در حدیث امیرمؤمنان به فرزندش آمده آن\u200cچنان از خدا خائف باش که اگر حسنات اهل زمین را بیاوری احتمال بده نپذیرد و آن\u200cچنان امیدوار باش که اگر گناهان اهل زمین را داشته باشی احتمال ده بیامرزد', ''),
28: ('إن عذاب ربهم غير مأمون', 'نمونه می\u200cگوید هیچ\u200cکس خود را از عذاب پروردگار در امان نمی\u200cبیند زیرا ممکن است کسی ایمان به روز جزا داشته باشد اما خود را مشمول مجازات نشمرد و حتی پیامبر فرمود هیچ\u200cکس با عملش وارد بهشت نمی\u200cشود مگر آنکه رحمت خدا شامل او شود و این بیم دائمی احساس مسئولیت پایدار می\u200cسازد', ''),
29: ('لفروجهم حافظون حفظ دامان', 'نمونه می\u200cگوید آنان دامان خویش را از بی\u200cعفتی حفظ می\u200cکنند و غریزه جنسی از غرائز سرکش انسان و سرچشمه بسیاری از گناهان است تا آنجا که در تمام پرونده\u200cهای مهم جنایی اثری از آن دیده می\u200cشود و کنترل و حفظ حدود آن از نشانه\u200cهای مهم تقواست و پس از نماز و انفاق و ایمان به جزا آمده است', ''),
30: ('إلا على أزواجهم استثنای همسر', 'نمونه می\u200cگوید بهره\u200cگیری جنسی آنان جز با همسرانشان نیست و در این بهره\u200cگیری سرزنشی بر آنان نیست و منطق اسلام هرگز محو کامل این غریزه نیست و تعبیر ازدواج همسران دائم و موقت را هر دو شامل می\u200cشود و گمان نفی ازدواج موقت از ندانستن آن است که آن هم نوعی ازدواج است و کنیزان نیز در حکم همسر با انضباط قانونی بودند', ''),
31: ('فأولئك هم العادون تجاوز از مرز', 'نمونه می\u200cگوید هر کس ماورای آن را طلب کند متجاوز و خارج از مرزهای الهی است و اسلام طرح جامعه\u200cای می\u200cریزد که هم به غرائز فطری در آن پاسخ داده شود و هم آلوده فحشا و فساد جنسی نباشد و این آیه تأکید بیشتر بر وصف پیشین و مرز بیداری اخلاق مؤمنان است', ''),
32: ('لأماناتهم وعهدهم راعون', 'نمونه می\u200cگوید آنان امانت\u200cها و عهد خود را رعایت می\u200cکنند و امانت معنای وسیعی دارد که امانت\u200cهای مادی مردم و امانت\u200cهای الهی و پیامبران و پیشوایان را شامل می\u200cشود و پست\u200cهای اجتماعی و حکومت از مهم\u200cترین امانات است و عهد نیز هر التزام مردمى و الهی را دربر می\u200cگیرد و پایبندی به آن\u200cها از مهم\u200cترین نشانه\u200cهای ایمان است', ''),
33: ('بشهاداتهم قائمون قیام به شهادت', 'نمونه می\u200cگوید آنان برای ادای شهادت حق قیام می\u200cکنند زیرا اقامه شهادت عادلانه و ترک کتمان آن از مهم\u200cترین پایه\u200cهای اقامه عدالت در جامعه بشری است و قرآن در آیات متعدد مسلمانان را به ادای شهادت حق دعوت کرده و کتمان را گناه شمرده و شهادت در فقه پایه اثبات بسیاری از حقوق فردی و اجتماعی است', ''),
34: ('على صلاتهم يحافظون محافظت بر نماز', 'نمونه می\u200cگوید آنان بر نماز خود محافظت می\u200cکنند و با توجه به قرائن این نماز اشاره به نماز واجب و آیه نخست اشاره به نافله است و محافظت حفظ آداب و شرایط و ارکان و حضور قلب است و این آغاز و پایان با نماز نشان می\u200cدهد نماز برترین وصف مؤمنان و مکتب عالی تربیت و تهذیب نفوس است', ''),
35: ('في جنات مكرمون گرامیان بهشت', 'نمونه می\u200cگوید کسانی که دارای این نه صفت\u200cاند در باغ\u200cهای بهشت جای دارند و از هر نظر گرامی داشته می\u200cشوند چرا گرامی نباشند در حالی که مهمانان خدایند و خداوند قادر و رحمان همه وسائل پذیرایی را برایشان فراهم ساخته و جنات و مکرمون اشاره به نعمت\u200cهای مادی و معنوی این گروه است', ''),
36: ('قبلك مهطعين شتاب کافران', 'نمونه می\u200cگوید این کافران را چه می\u200cشود که با سرعت نزد تو می\u200cآیند و مهطع کسی است که گردن می\u200cکشد و با سرعت راه می\u200cرود در جست\u200cوجوی چیزی و مشرکان هنگامی که پیامبر آیات معاد را می\u200cخواند از هر گوشه می\u200cآمدند و می\u200cگفتند اگر معادی باشد وضع ما از مؤمنان بهتر است و قرآن به پاسخ آنان باز می\u200cگردد', ''),
37: ('عن اليمين وعن الشمال عزين', 'نمونه می\u200cگوید آنان از راست و چپ گروه\u200cگروه می\u200cآیند و عزین جمع عزة به معنای جماعت\u200cهای پراکنده است و ریشه آن نسبت\u200cدادن است و مشرکان خودخواه مرفه بودن زندگی مادی خود را که غالبا از راه\u200cهای نامشروع حاصل شده بود دلیل بلندی مقامشان نزد خدا می\u200cپنداشتند و برای خود در قیامت نیز مقاماتی قائل بودند', ''),
38: ('أيطمع كل امرئ أن يدخل جنة نعيم', 'نمونه می\u200cگوید آیا هر یک از آنان طمع دارد در بهشت پرنعمت وارد شود و این طمع را گاه به صورت استهزا می\u200cگفتند و قرآن می\u200cپرسد با کدام ایمان و با کدام عمل چنین شایستگی برای خود قائل\u200cاند و پاسخ آنکه نه ایمان دارند و نه عمل و ادعای بی\u200cاساس آنان از سر غرور ثروت دنیایی است', ''),
39: ('إنا خلقناهم مما يعلمون', 'نمونه می\u200cگوید هرگز چنین نیست ما آنها را از آنچه خودشان می\u200cدانند آفریده\u200cایم از نطفه\u200cای بی\u200cارزش و این جمله هم غرور آنان را درهم می\u200cشکند و هم پاسخی به استهزاکنندگان معاد است که خالق انسان از نطفه قادر است پس از خاک\u200cشدن لباس حیات در تن او بپوشاند و شرف انسان تنها به ایمان و عمل صالح است که آنان فاقد آن\u200cاند', ''),
40: ('برب المشارق والمغارب إنا لقادرون', 'نمونه می\u200cگوید سوگند به پروردگار مشرق\u200cها و مغرب\u200cها که ما قادریم و خورشید هر روز از نقطه\u200cای تازه طلوع و در نقطه\u200cای تازه غروب می\u200cکند پس به تعداد روزهای سال مشرق و مغرب داریم و خدایی که چنین نظامی دقیق را میلیون\u200cها سال برقرار نگه داشته قادر است انسان را به زندگی بازگرداند', ''),
41: ('أن نبدل خيرا منهم', 'نمونه می\u200cگوید قادریم جای آنها را به کسانی بدهیم که از آنها بهترند و ما هرگز مغلوب نخواهیم شد و این جمله یا اشاره به بازگرداندن آنان به حیات نوین و کامل\u200cتر است یا آنکه گروهی شایسته\u200cتر جانشین آنان شوند و اصرار بر ایمان آنان از نیاز و عجز نیست بلکه مصلحت هدایت بشر است', ''),
42: ('فذرهم يخوضوا ويلعبوا', 'نمونه می\u200cگوید آنها را به حال خود واگذار تا در باطل خود فرو روند و بازی کنند تا روز موعود خود را ملاقات نمایند بیش از این استدلال و موعظه لازم نیست و بگذار در اباطیل خود غوطه\u200cور باشند و همچون کودکان سرگرم بازی تا همه\u200cچیز را با چشم خود ببینند و این آیه با همین تعبیر در سوره زخرف نیز آمده است', ''),
43: ('يخرجون من الأجداث سراعا', 'نمونه می\u200cگوید روزی که از قبرها به سرعت خارج می\u200cشوند گویی به سوی بت\u200cهایشان می\u200cدوند و أجداث قبرها و نصب نشانه\u200cها و بت\u200cهایی است که به سوی آن می\u200cشتافتند و در دنیا آن شتاب را برای بت\u200cها داشتند و در قیامت با همان شتاب درمانده به سوی حساب رانده می\u200cشوند و این تناسب تلخی آشکاری دارد', ''),
44: ('خاشعة أبصارهم ترهقهم ذلة', 'نمونه می\u200cگوید در حالی که چشم\u200cهای آنان از شدت وحشت به زیر افتاده و ذلت و خواری آنان را پوشانده می\u200cگویند این همان روزی است که به شما وعده داده می\u200cشد و پایان سوره سرنوشت استهزاکنندگان و مغروران را در برابر چشم می\u200cنهد و خشوع چشم و ذلت فراگیر مهر پایان این انذار است', ''),
}

PURPOSE = 'سوره معارج در نمونه سوره\u200cای مکی با چهل و چهار آیه است که با تقاضای عذاب از سوی سائل و صحنه\u200cهای قیامت آغاز می\u200cشود و با اوصاف نه\u200cگانه نمازگزاران و سرنوشت کافران مغرور پایان می\u200cیابد'

_CORP = {}
for _r in json.loads((ROOT / "static" / "offline-corpus.json").read_text(encoding="utf-8"))["verses"]:
    _CORP[(_r[0], _r[1])] = (_r[2], _r[3])
_MOYJ = json.loads((ROOT / "static" / "tafsir" / "arabic-moyassar-quranenc-1.0.0.json").read_text(encoding="utf-8"))["verses"]


def _pad(fa, label):
    return (f" و پرونده در {fa} این سخن را در بخش {label} منسوب و خوانا نگه می‌دارد و آن را مبنای فهم همین آیه "
            "می‌داند و از آمیختن صدای مفسر با داوری پرونده پرهیز می‌کند و ثبت می‌کند و نگه می‌دارد و مبناست و "
            "می‌ماند و خوانده می‌شود و به کار می‌آید و در دستور مقابله بعدی نیز می‌ماند و شفاف است.")


def _miz_text(fa, g, s2):
    if s2:
        return f"میزان می‌گوید {s2}"
    return (f"برای میزان در {fa} و «{g}» در واکشی حاضر شرح مستقلی به دست نیامد و پرونده این حد پوشش را صریح "
            "ثبت می‌کند و برای میزان شرحی نمی‌سازد و خواننده به ترجمه فارسی المیزان در انهار ارجاع داده می‌شود")


def _mugh_text(fa, g):
    return (f"برای الکاشف مغنیه در {fa} و «{g}» در واکشی حاضر متن آنلاین مقابله‌شده‌ای در دست نیست و پرونده این حد "
            "پوشش را صریح ثبت می‌کند و برای مغنیه شرحی نمی‌سازد و مقابله متن چاپی الکاشف در دستور کار سطح full می‌ماند")


def _tasn_text(fa, g):
    return (f"برای تسنیم جوادی آملی در {fa} و «{g}» در واکشی حاضر متن آنلاین مقابله‌شده‌ای در دست نیست و پرونده این "
            "حد پوشش را صریح ثبت می‌کند و برای تسنیم شرحی نمی‌سازد و مقابله متن چاپی تسنیم در دستور کار بعدی می‌ماند")


def make(n, g, s1, s2, purpose):
    fa = f"{SNAME} {SFA}:{n}"
    vid = f"{SNUM}:{n}"
    uth, _fool = _CORP[(SNUM, n)]
    moy = _MOYJ[str(SNUM)][str(n)]["text"]
    miz = _miz_text(fa, g, s2)
    base = {
        'notes': [
            rec_base(f"متن آیه در متن عثمانی محلی «{uth}» است و فولادوند مضمونِ {g} را می‌آورد و پرونده این ضبط را مبنای ارجاع نگه می‌دارد" + _pad(fa, "یادداشت"), LOCALY),
            rec_base(f"المیسر می‌گوید {moy} و این تنها مدخل المیسر در این پرونده است" + _pad(fa, "یادداشت"), MOY(n)),
            rec_base(f"طبری برای «{g}» در {fa} در واکشی حاضر شرح مستقلی ندارد و پرونده این حد پوشش را صریح ثبت می‌کند و برای طبری شرحی نمی‌سازد و خواننده به جامع البیان ارجاع داده می‌شود" + _pad(fa, "پوشش"), TAB(n)),
            rec_base(f"نمونه می‌گوید {s1}" + _pad(fa, "یادداشت"), NEM(n)),
        ],
        'context': [
            rec_base(f"در بافت همین سوره {miz}" + _pad(fa, "بافت"), MIZ(n)),
            rec_base(f"نمونه می‌گوید {s1}" + _pad(fa, "بافت"), NEM(n)),
            rec_base(_mugh_text(fa, g) + _pad(fa, "پوشش"), MUGH(n)),
            rec_base(f"{purpose} و این آیه در همان سیاق «{g}» را می‌نشاند و پیوندش با آیات همسایه در پرونده نگه داشته می‌شود" + _pad(fa, "بافت"), NEM(n)),
        ],
        'classical': [
            rec_base(f"طبری در واکشی حاضر برای {fa} و «{g}» شرح مستقلی ندارد و پرونده مدخل کلاسیک نخست را گزارش پوشش نگه می‌دارد و خواننده برای شرح جامع البیان به مقابله بعدی سپرده می‌شود" + _pad(fa, "کلاسیک"), TAB(n)),
            rec_base(f"درباره «{g}» برای قرطبی شرح مستقلی در واکشی حاضر در دست نیست و پرونده این حد پوشش را صریح ثبت می‌کند و برای قرطبی شرحی نمی‌سازد و آن را خلأ پوشش منبع می‌خواند" + _pad(fa, "کلاسیک"), QUR(n)),
            rec_base(f"صافی در واکشی حاضر برای {fa} و «{g}» شرح مستقلی برنگرداند و پرونده مدخل شیعی کلاسیک را گزارش پوشش ثبت می‌کند و شرح اصلی از منابع شیعی معاصر است و این تفکیک سنت‌ها نگه داشته می‌شود" + _pad(fa, "کلاسیک"), SAFI(n)),
            rec_base(f"نمونه می‌گوید {s1} و پرونده این شرح شیعی معاصر را در کنار گزارش پوشش کلاسیک‌ها می‌نشاند و صدای مفسرها را درهم نمی‌آمیزد" + _pad(fa, "کلاسیک متأخر"), NEM(n)),
        ],
        'modern': [
            rec_base(f"نمونه می‌گوید {s1}" + _pad(fa, "معاصر"), NEM(n)),
            rec_base(f"نمونه می‌گوید {s1} و این خوانش در تفسیر نمونه ذیل همین آیه آمده و پرونده آن را جدا از داوری خود نگه می‌دارد" + _pad(fa, "معاصر"), NEM(n)),
            rec_base(f"سعدی در واکشی حاضر برای {fa} و «{g}» شرح مستقلی برنگرداند و پرونده مدخل سنی معاصر دوم را گزارش پوشش ثبت می‌کند و شرح سنی معاصر اصلی از المیسر در بخش یادداشت آمده و این تفکیک نگه داشته می‌شود" + _pad(fa, "پوشش"), SAD(n)),
            rec_base(_tasn_text(fa, g) + _pad(fa, "پوشش"), TASN(n)),
        ],
        'critical': [
            rec_base(f"در خوانش گفتمانی {fa} بار معنای آیه در ساخت خطاب «{g}» است و جای گوینده و مخاطب و ترتیب جمله‌ها معنایی فراتر از گزارش رویداد می‌سازد و تحلیل فیرکلاف‌خوان آن را روشن می‌کند و درباره اشخاص داوری نمی‌کند" + _pad(fa, "انتقادی"), FAIRCLOUGH),
            rec_base(f"در چارچوب تیلور «{g}» در {fa} را می‌توان در افق معنایی انسان در برابر خدا و جامعه خواند و این خوانش تحلیل می‌ماند و با نقل مستقیم یکی گرفته نمی‌شود" + _pad(fa, "انتقادی"), TAYLOR),
            rec_base(f"از منظر تاریخ دریافت {fa} و «{g}» در هر دوره با مسئله ایمان و روابط اجتماعی خوانده شده و پرونده افق‌های دریافت را جدا و منسوب نگه می‌دارد و در یک صدا ذوب نمی‌کند" + _pad(fa, "انتقادی"), HOURANI),
            rec_base(f"سنجش تطبیقی شرح‌ها در {fa} نشان می‌دهد نمونه «{g}» را با نکته‌های تربیتی و میزان آن را در چارچوب سیاقی خود می‌خوانند و ضوابط تفسیر تطبیقی سطوح و خلأها را جدا و منسوب نگه می‌دارد" + _pad(fa, "انتقادی"), J_TATBIQ),
        ],
        'research': [
            rec_base(f"پرسش پژوهشی {fa} درباره «{g}» آن است که این موضوع در پژوهش‌های داوری‌شده تخصصی چگونه ارزیابی می‌شود و پاسخ نیازمند مقابله مقاله‌های تخصصی و خود منابع است و از ساختن داوری بی‌سند پرهیز می‌شود" + _pad(fa, "پژوهش"), J_TATBIQ),
            rec_base(f"در ادبیات پژوهشی معاصر از منظر نظم نزد جرجانی چیدمان واژگان {fa} در «{g}» نظم معنای آیه را می‌سازد و سنجش آن مسیر تحقیق بلاغی آینده این آیه را روشن می‌کند" + _pad(fa, "پژوهش"), JURJANI),
            rec_base(f"چارچوب‌های ایزوتسو و فیلمور و معناشناسی شناختی در {fa} چنین به کار می‌آیند که «{g}» در میدان معنایی قرآن و قاب تحلیلی همین آیه خوانده شود و این کاربرد چارچوب‌مند جای نقل مستقیم را نمی‌گیرد" + _pad(fa, "پژوهش"), IZUTSU),
            rec_base(_mugh_text(fa, g) + _pad(fa, "پژوهش"), MUGH(n)),
        ],
    }
    pa = _pad(fa, "افزوده")
    ext = X(vid,
            (f"{g} در مقایسه مضمونی سنت‌ها", MIZ(n), f"در مقایسه مضمونی «{g}» در {fa} با مضامین هم‌خانواده در سنت‌های تفسیری شیعی و سنی پیوند تاریخی مستقیمی در منابع مقابله‌شده ادعا نشده و هر سنت افق خوانش خود را دارد" + pa),
            (f"پاسخ منسوب درباره {g}", NEM(n), f"نمونه می‌گوید {s1} و پرونده این پاسخ منسوب را داوری نهایی نمی‌خواند" + pa),
            (f"مبانی {g} نزد میزان", MIZ(n), miz + pa),
            (f"تحلیل زبانی {g}", NEM(n), f"واژگان کلیدی «{g}» در {fa} در پیوند معنایی با سیاق سوره خوانده می‌شوند و نمونه و میزان هر یک وجهی از این پیوند را از لغت و سیاق برمی‌گیرند" + pa),
            (f"هدایت در {g} نزد نمونه", NEM(n), f"نمونه می‌گوید {s1}" + pa),
            (f"پوشش منابع {g} ", NEM(n), f"در بافت تاریخی {fa} هر جا شرح مستقلی از منابع کلاسیک در واکشی حاضر برنگشت پرونده مدخل پوشش ثبت کرده و هوارانی چارچوب عمومی است و نبود پژوهش را اثبات نمی‌کند" + pa))
    return {"note": f"«{g}».", "a": n, "base": base, "ext": ext}


dossiers = {}
for _n, (_g, _s1, _s2) in V.items():
    dossiers[f"{SNUM}:{_n}"] = make(_n, _g, _s1, _s2, PURPOSE)


for vid, spec in dossiers.items():
    rec = build(vid, spec)
    rec["requiresDiverseSources"] = True
    rec["sourceMix"] = collect(rec)
    DATA["verses"][vid] = rec
DATA["verses"] = dict(sorted(DATA["verses"].items(), key=lambda kv: tuple(int(x) if x.isdigit() else 0 for x in kv[0].split(':'))))
_main = dict(DATA); _part = {"verses": {k: v for k, v in DATA["verses"].items() if int(k.split(":")[0]) >= 30}}
_main["verses"] = {k: v for k, v in DATA["verses"].items() if int(k.split(":")[0]) < 30}
PATH.write_text(json.dumps(_main, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
PATH2.write_text(json.dumps(_part, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
print("records:", len(DATA["verses"]))
